//! The Tauri context is generated by `crates/hole/build.rs`, never by the
//! `tauri::generate_context!()` macro.
//!
//! The macro writes every embedded asset into the package's `OUT_DIR` *during
//! the rustc run of the unit that expands it*, while cargo dates that unit's
//! fingerprint from the start of the compile. A fresh `OUT_DIR` therefore
//! always leaves the unit stale for the next cargo command, and the bin and its
//! `cfg(test)` build (same `src/main.rs`) also write the same files in
//! parallel (bindreams/hole#1087). The build script writes the assets before
//! any unit that reads them starts; `tauri::tauri_build_context!()` only
//! `include!`s the generated file, so it has no such effect and appears once.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

const FORBIDDEN_MACRO: &str = "generate_context";
const REQUIRED_MACRO: &str = "tauri_build_context";

/// How often a source names a macro, counted over its token stream.
#[derive(Debug, PartialEq, Eq)]
struct Mentions {
    /// Every identifier equal to the macro's name: an invocation, a path to it,
    /// a `use` of it (renamed or not), a `macro_rules!` of that name.
    named: usize,
    /// The subset directly followed by `!`.
    invoked: usize,
}

/// Count the identifiers named `name` in `source`, descending into every group,
/// so a call inside another macro's body (`vec![..]`, `cfg_if!{..}`, a
/// `macro_rules!` body) is seen: syn does not parse those bodies. Comments,
/// doc comments and string literals are not identifiers. `origin` names the
/// file in the error when `source` does not lex.
fn mentions_in(source: &str, name: &str, origin: &Path) -> Result<Mentions, String> {
    use proc_macro2::{Spacing, TokenStream, TokenTree};

    fn walk(stream: TokenStream, name: &str, found: &mut Mentions) {
        let mut tokens = stream.into_iter().peekable();
        while let Some(tree) = tokens.next() {
            match tree {
                TokenTree::Ident(ident) if ident == name => {
                    found.named += 1;
                    let bang = matches!(tokens.peek(), Some(TokenTree::Punct(p)) if p.as_char() == '!' && p.spacing() == Spacing::Alone);
                    found.invoked += usize::from(bang);
                }
                TokenTree::Group(group) => walk(group.stream(), name, found),
                _ => {}
            }
        }
    }

    let stream: TokenStream = source.parse().map_err(|e| format!("lex {}: {e}", origin.display()))?;
    let mut found = Mentions { named: 0, invoked: 0 };
    walk(stream, name, &mut found);
    Ok(found)
}

/// The `.rs` files cargo compiles for the workspace at `manifest`, sorted: for
/// each member, the directory tree of every target's root file (`src/`,
/// `tests/`, `src/bin/`, ...), or just the root file when it sits beside the
/// manifest (`build.rs`). The set comes from cargo's own view of the workspace,
/// so a copy of the tree, a nested checkout, build output and a stray `.rs` file
/// outside those trees are never in it.
fn first_party_sources(manifest: &Path) -> Vec<PathBuf> {
    fn add_tree(dir: &Path, found: &mut BTreeSet<PathBuf>) {
        for entry in std::fs::read_dir(dir).unwrap_or_else(|e| panic!("read_dir {}: {e}", dir.display())) {
            let path = entry.expect("dir entry").path();
            if path.is_dir() {
                add_tree(&path, found);
            } else if path.extension().is_some_and(|e| e == "rs") {
                found.insert(path);
            }
        }
    }

    let metadata = cargo_metadata::MetadataCommand::new()
        .manifest_path(manifest)
        .no_deps()
        .exec()
        .expect("cargo metadata");
    let mut found = BTreeSet::new();
    for package in metadata.workspace_packages() {
        let package_dir = package.manifest_path.parent().expect("manifest has a directory");
        for target in &package.targets {
            let root_file = target.src_path.as_std_path();
            let dir = root_file.parent().expect("target root has a directory");
            if dir == package_dir.as_std_path() {
                found.insert(root_file.to_path_buf());
            } else {
                add_tree(dir, &mut found);
            }
        }
    }
    found.into_iter().collect()
}

/// Where the context macros are named across `sources`.
struct Sites {
    /// Every file naming the forbidden macro, once per mention.
    forbidden: Vec<PathBuf>,
    /// Every file invoking the required macro, once per invocation.
    required: Vec<PathBuf>,
}

fn context_macro_sites(sources: &[PathBuf]) -> Sites {
    let mut sites = Sites {
        forbidden: Vec::new(),
        required: Vec::new(),
    };
    for path in sources {
        let source = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
        // A cheap pre-filter; the token scan below decides.
        let contains = |name| source.contains(name);
        if !contains(FORBIDDEN_MACRO) && !contains(REQUIRED_MACRO) {
            continue;
        }
        let scan = |name| mentions_in(&source, name, path).unwrap_or_else(|e| panic!("{e}"));
        sites
            .forbidden
            .extend(std::iter::repeat_n(path.clone(), scan(FORBIDDEN_MACRO).named));
        sites
            .required
            .extend(std::iter::repeat_n(path.clone(), scan(REQUIRED_MACRO).invoked));
    }
    sites
}

// Scanner -------------------------------------------------------------------------------------------------------------

fn mentions(source: &str, name: &str) -> Mentions {
    mentions_in(source, name, Path::new("fixture.rs")).expect("fixture lexes")
}

fn once_invoked() -> Mentions {
    Mentions { named: 1, invoked: 1 }
}

#[skuld::test]
fn a_qualified_invocation_is_counted() {
    assert_eq!(
        mentions("fn f() { run(tauri::generate_context!()); }", "generate_context"),
        once_invoked()
    );
}

#[skuld::test]
fn a_bare_macro_path_is_counted() {
    assert_eq!(
        mentions("fn f() { run(generate_context!()); }", "generate_context"),
        once_invoked()
    );
}

#[skuld::test]
fn every_invocation_is_counted_wherever_it_sits() {
    let source = "#[cfg(not(test))] fn a() { tauri::generate_context!(); } \
                  mod m { fn b() { tauri::generate_context!(); } }";
    assert_eq!(mentions(source, "generate_context"), Mentions { named: 2, invoked: 2 });
}

#[skuld::test]
fn an_invocation_inside_another_macros_body_is_counted() {
    for source in [
        "fn f() { let _ = vec![tauri::generate_context!()]; }",
        "fn f() { dbg!(run(tauri::generate_context!())); }",
        "cfg_if! { if #[cfg(unix)] { fn f() { tauri::generate_context!(); } } }",
        "macro_rules! m { () => { tauri::generate_context!() }; }",
        "#[attr(tauri::generate_context!())] fn f() {}",
    ] {
        assert_eq!(mentions(source, "generate_context"), once_invoked(), "{source}");
    }
}

#[skuld::test]
fn a_renamed_import_is_counted() {
    // The renamed call site `ctx!()` does not repeat the name; the `use` does.
    let source = "use tauri::generate_context as ctx; fn f() { ctx!(); }";
    assert_eq!(mentions(source, "generate_context"), Mentions { named: 1, invoked: 0 });
    let braced = "use tauri::{generate_context as ctx, Builder}; fn f() { ctx!(); }";
    assert_eq!(mentions(braced, "generate_context"), Mentions { named: 1, invoked: 0 });
}

#[skuld::test]
fn a_mention_in_a_comment_string_or_doc_is_not_counted() {
    let source =
        "/// `tauri::generate_context!()` here\n// tauri::generate_context!()\nfn f() { let _ = \"generate_context!()\"; }";
    assert_eq!(mentions(source, "generate_context"), Mentions { named: 0, invoked: 0 });
}

#[skuld::test]
fn other_macros_are_not_counted() {
    for (source, name) in [
        ("fn f() { tauri::generate_handler![a]; }", "generate_context"),
        ("fn f() { tauri::tauri_build_context!(); }", "generate_context"),
        ("fn f() { tauri::generate_context!(); }", "tauri_build_context"),
    ] {
        assert_eq!(mentions(source, name), Mentions { named: 0, invoked: 0 }, "{source}");
    }
}

#[skuld::test]
fn a_source_that_does_not_lex_is_reported_with_its_path() {
    let err = mentions_in("fn f( {", "generate_context", Path::new("crates/x/src/y.rs")).unwrap_err();
    assert!(err.contains("crates/x/src/y.rs"), "{err}");
}

// Source discovery ----------------------------------------------------------------------------------------------------

/// A one-member workspace in a temp dir, plus the files that must not count:
/// a copy of the tree with no `.git` (`cp -R`, a tarball), a stray `.rs` at the
/// root, and a stray `.rs` inside the member but outside its target trees. Every
/// file is named after what it holds so the assertions read as a list.
struct Fixture {
    root: tempfile::TempDir,
}

impl Fixture {
    fn new() -> Self {
        let root = tempfile::tempdir().expect("tempdir");
        let fixture = Fixture { root };
        fixture.write(
            "Cargo.toml",
            "[workspace]\nmembers = [\"crates/a\"]\nresolver = \"2\"\n",
        );
        fixture.write(
            "crates/a/Cargo.toml",
            "[package]\nname = \"a\"\nversion = \"0.0.0\"\nedition = \"2021\"\n",
        );
        fixture
    }

    fn write(&self, rel: &str, contents: &str) -> PathBuf {
        let path = self.root.path().join(rel);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, contents).unwrap();
        path
    }

    fn manifest(&self) -> PathBuf {
        self.root.path().join("Cargo.toml")
    }
}

#[skuld::test]
fn only_a_members_target_trees_are_first_party_source() {
    let fx = Fixture::new();
    let mut expected = vec![
        fx.write("crates/a/src/lib.rs", "pub mod deep;"),
        fx.write("crates/a/src/deep/er.rs", ""),
        fx.write("crates/a/src/bin/tool.rs", "fn main() {}"),
        fx.write("crates/a/tests/it.rs", ""),
        fx.write("crates/a/build.rs", "fn main() {}"),
    ];
    expected.sort();
    // Not part of any build: a copy of the tree (no `.git`), a linked worktree
    // and a clone (with one), stray files at the root and inside the member.
    fx.write("copy/crates/a/src/lib.rs", "");
    fx.write("copy/crates/a/Cargo.toml", "");
    fx.write("wt/.git", "gitdir: x");
    fx.write("wt/crates/a/src/lib.rs", "");
    fx.write("clone/.git/HEAD", "");
    fx.write("clone/crates/a/src/lib.rs", "");
    fx.write("old_main.rs", "");
    fx.write("crates/a/scratch/old.rs", "");
    fx.write("crates/a/target/debug/build/gen.rs", "");

    assert_eq!(first_party_sources(&fx.manifest()), expected);
}

#[skuld::test]
fn a_call_in_a_members_nested_module_is_caught_and_one_in_a_copy_is_not() {
    let fx = Fixture::new();
    fx.write("crates/a/src/lib.rs", "pub mod deep;");
    fx.write("crates/a/src/deep/er.rs", "fn f() { tauri::generate_context!(); }");
    fx.write("copy/crates/a/src/lib.rs", "fn f() { tauri::generate_context!(); }");
    fx.write("old_main.rs", "fn f() { tauri::generate_context!(); }");

    let found = context_macro_sites(&first_party_sources(&fx.manifest()));
    assert_eq!(found.forbidden, vec![fx.root.path().join("crates/a/src/deep/er.rs")]);
    assert!(found.required.is_empty());
}

// Workspace -----------------------------------------------------------------------------------------------------------

/// `repo_root()` rather than `env!("CARGO_MANIFEST_DIR")`: this binary runs
/// from a nextest archive under `--workspace-remap`, where the build-time path
/// does not exist.
#[skuld::test]
fn the_tauri_context_comes_from_the_build_script() {
    let root = crate::repo_root().expect("repo root");
    let main_rs = root.join("crates").join("hole").join("src").join("main.rs");

    let Sites { forbidden, required } = context_macro_sites(&first_party_sources(&root.join("Cargo.toml")));

    assert!(
        forbidden.is_empty(),
        "`{FORBIDDEN_MACRO}` is named at {forbidden:?} (an invocation, a path or a `use`); the macro writes OUT_DIR assets during its \
         own unit's compile and leaves that unit stale for the next cargo command \
         (bindreams/hole#1087). Generate the context in crates/hole/build.rs and use \
         `tauri::{REQUIRED_MACRO}!()`"
    );
    // The scan's own precondition: it read the file the guard is about. A
    // guard that reads nothing passes forever.
    assert_eq!(
        required,
        vec![main_rs.clone()],
        "`tauri::{REQUIRED_MACRO}!()` must appear exactly once, in {}",
        main_rs.display()
    );
}
